import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

const ParkingMap = () => {
  const [parkingData, setParkingData] = useState([]);
  const [center, setCenter] = useState([36.5, 127.8]); // 대한민국 중심 좌표

  useEffect(() => {
    fetch('/api/parking')
      .then(res => res.json())
      .then(data => {
        setParkingData(data.data || []);
        if (data.data && data.data.length > 0) {
          setCenter([data.data[0].coordinates.lat, data.data[0].coordinates.lon]);
        }
      });
  }, []);

  return (
    <div style={{ height: '500px', width: '100%' }}>
      <MapContainer center={center} zoom={8} style={{ height: '100%', width: '100%' }}>
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution="&copy; OpenStreetMap contributors"
        />
        {parkingData.map((parking, idx) => (
          <Marker key={parking.id || idx} position={[parking.coordinates.lat, parking.coordinates.lon]}>
            <Popup>
              <strong>{parking.name}</strong><br />
              {parking.address}<br />
              {parking.fee}
            </Popup>
          </Marker>
        ))}
      </MapContainer>
    </div>
  );
};

export default ParkingMap;
